select PBC_PROD_ID, prod_name,ACCOUNT_ID,PROD_ID,ORG_CODE from ( select ifnull(T3.pbc_code,t1.PBC_PROD_ID) PBC_PROD_ID,prod_name,ACCOUNT_ID,PROD_ID,ORG_CODE, rank() over (partition by PBC_PROD_ID order by IFNULL(update_time,create_time) desc) ranknum from PBC_PRD_BASEINFO_SUB_NEW t1 LEFT JOIN( SELECT inside_prod_id, pbc_code FROM pbc_prod_assetpool_code WHERE status='E' AND code_type='01' )t3 ON t3.inside_prod_id=t1.PROD_ID where STATUS != 'D'
AND (PBC_PROD_ID LIKE concat(concat('%', #{search}),'%') or prod_name LIKE concat(concat('%', #{search}),'%') or pbc_code LIKE concat(concat('%', #{search}),'%'))
) as t where ranknum = 1

